import type { QuestionSeed, QuizSeed } from "./types";

export const psychologieMatiere = {
  nom: "Psychologie",
  description: "Introduction, méthodes et statistiques, psychologie cognitive, développementale, sociale et biologique.",
};

const notions = {
  introduction: "Introduction à la psychologie et grandes approches",
  methodologie: "Méthodologie de la recherche",
  statistiques: "Statistiques en psychologie",
  cognitive: "Psychologie cognitive",
  developpement: "Psychologie du développement",
  sociale: "Psychologie sociale",
  neuro: "Psychobiologie et neuropsychologie",
  ethique: "Éthique et déontologie",
} as const;

// Progression alignée sur les maquettes de Rennes 2 et Paris Nanterre ; la déontologie reste transversale.
type NotionKey = keyof typeof notions;
type OptionSeed = readonly [texte: string, correcte: boolean];

function q(
  id: string,
  notion: NotionKey,
  niveau: number,
  type: "qcm" | "qcu",
  intitule: string,
  explication: string,
  reponses: OptionSeed[],
): QuestionSeed {
  const decalage = Number(id.slice(-2)) % reponses.length;
  const reponsesMelangees = [...reponses.slice(decalage), ...reponses.slice(0, decalage)];
  return {
    id,
    notion: notions[notion],
    niveau,
    type,
    intitule,
    explication,
    reponses: reponsesMelangees.map(([texte, correcte]) => ({ texte, correcte })),
  };
}

function qc(
  id: string,
  notion: NotionKey,
  niveau: number,
  type: "qcm" | "qcu",
  intitule: string,
  explication: string,
  reponsesCorrectes: string[],
  distracteurs: string[],
): QuestionSeed {
  return q(id, notion, niveau, type, intitule, explication, [
    ...reponsesCorrectes.map((texte) => [texte, true] as const),
    ...distracteurs.map((texte) => [texte, false] as const),
  ]);
}

